(()=>{
const wall=document.querySelector('#gallery');if(!wall)return;
const filters=[...document.querySelectorAll('[data-filter]')],viewer=document.querySelector('#viewer'),body=document.querySelector('#viewer-body');viewer.classList.add('gallery-viewer');viewer.setAttribute('aria-labelledby','viewer-title');
let active='All',scope='single',current=null,opener=null,layoutFrame;
const visible=()=>{const rank=new Map((portfolioOrders[active]||[]).map((id,i)=>[id,i]));return portfolioPhotos.filter(p=>active==='All'||p.category===active).sort((a,b)=>(rank.get(a.id)??999)-(rank.get(b.id)??999))};
const related=()=>(current.collectionGroup||current.personGroup)?portfolioPhotos.filter(p=>(p.collectionGroup||p.personGroup)===(current.collectionGroup||current.personGroup)):[];
const sequence=()=>scope==='collection'?related():visible();
function layout(){cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{const style=getComputedStyle(wall),unit=parseFloat(style.gridAutoRows),gap=parseFloat(style.rowGap);wall.querySelectorAll('.wall-card:not([hidden])').forEach(card=>{const height=card.querySelector('.wall-image').getBoundingClientRect().height+card.querySelector('.wall-meta').getBoundingClientRect().height;card.style.gridRowEnd='span '+Math.ceil((height+gap)/(unit+gap))})})}
new ResizeObserver(layout).observe(wall);
function filter(name,write=true){active=filters.some(b=>b.dataset.filter===name)?name:'All';filters.forEach(b=>{const on=b.dataset.filter===active;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});wall.querySelectorAll('[data-cat]').forEach(b=>b.hidden=active!=='All'&&b.dataset.cat!==active);const cards=new Map([...wall.querySelectorAll('[data-photo]')].map(b=>[b.dataset.photo,b]));visible().forEach(p=>wall.appendChild(cards.get(p.id)));if(write){const u=new URL(location.href);active==='All'?u.searchParams.delete('category'):u.searchParams.set('category',active);history.replaceState(null,'',u)}layout()}
filters.forEach(b=>b.onclick=()=>filter(b.dataset.filter));filter(new URL(location.href).searchParams.get('category')||'All',false);
function render(){const focused=body.contains(document.activeElement)?document.activeElement:null;const focusKey=focused?.dataset.direction||focused?.dataset.viewId||(focused?.classList.contains('scope-button')?'scope':null);const list=sequence(),rel=related();document.querySelector('#viewer-title').textContent=current.title;
body.innerHTML=`<div class="viewer-stage"><img class="viewer-photo" src="/assets/${current.id}.jpg" alt="${current.alt}" width="${current.width}" height="${current.height}"></div><div class="viewer-controls"><button type="button" aria-label="Previous photograph" data-direction="-1" ${list.length<2?'disabled':''}>‹</button><button type="button" data-direction="1" ${list.length<2?'disabled':''} aria-label="Next photograph">›</button></div>${scope==='collection'?`<div class="viewer-thumbnails" aria-label="Photographs of the same subject">${rel.map(p=>`<button type="button" data-view-id="${p.id}" aria-label="View ${p.title}" aria-current="${p.id===current.id}"><img src="/assets/${p.id}-thumb.jpg" alt="" loading="lazy"></button>`).join('')}</div>`:''}`;
body.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>move(Number(b.dataset.direction)));body.querySelectorAll('[data-view-id]').forEach(b=>b.onclick=()=>{current=portfolioPhotos.find(p=>p.id===b.dataset.viewId);render()});const toggle=body.querySelector('.scope-button');if(toggle)toggle.onclick=()=>{scope=scope==='single'?'collection':'single';render()};if(focusKey){const target=focusKey==='scope'?body.querySelector('.scope-button'):body.querySelector('[data-direction="'+focusKey+'"],[data-view-id="'+focusKey+'"]');(target||document.querySelector('#close-viewer')).focus({preventScroll:true})}}
function move(dir){const list=sequence();if(list.length<2)return;current=list[(list.findIndex(p=>p.id===current.id)+dir+list.length)%list.length];render()}
wall.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{opener=b;current=portfolioPhotos.find(p=>p.id===b.dataset.photo);scope=related().length>1?'collection':'single';render();viewer.showModal();viewer.scrollTop=0;document.querySelector('#close-viewer').focus()});viewer.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});viewer.addEventListener('close',()=>opener?.focus({preventScroll:true}));let touch=null;body.addEventListener('touchstart',e=>{if(e.target.closest('.viewer-stage'))touch=[e.changedTouches[0].clientX,e.changedTouches[0].clientY]},{passive:true});body.addEventListener('touchend',e=>{if(touch){const dx=e.changedTouches[0].clientX-touch[0],dy=e.changedTouches[0].clientY-touch[1];if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy))move(dx<0?1:-1);touch=null}},{passive:true});
})();
